wtner-repo/mobile/src/screens/ProofScreen.tsx"},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"/Users/ff/Desktop/ProjectsAI/ProjectsHackathons/005-tencent/Pawtner-repo/mobile/src/screens/ProofScreen.tsx","content":"     1:import { useRef, useState } from "react";
     2:import { useTranslation } from "react-i18next";
     3:import { Icon } from "../components/Icon";
     4:import { FullCard } from "../components/FullCard";
     5:import { api } from "../lib/api";
     6:import type { PillDescribeResponse, PillVerifyResponse } from "../../../shared/contract";
     7:import type { BackAction } from "../lib/navigation";
     8:
     9:type CheckState =
    10:  | { kind: "idle" }
    11:  | { kind: "checking" }
    12:  | { kind: "described"; result: PillDescribeResponse }
    13:  | { kind: "verified"; result: PillVerifyResponse }
    14:  | { kind: "error"; message: string };
    15:
    16:export function ProofScreen({
    17:  back,
    18:  onVerified,
    19:  petName,
    20:  medicationName,
    21:  medicationId,
    22:}: {
    23:  back: BackAction;
    24:  onVerified: (photoUrl: string | null) => void | Promise<void>;
    25:  petName: string;
    26:  medicationName?: string;
    27:  medicationId?: string;
    28:}) {
    29:  const { t } = useTranslation();
    30:  const [captured, setCaptured] = useState(false);
    31:  const [photoUrl, setPhotoUrl] = useState<string | null>(null);
    32:  const [photoFile, setPhotoFile] = useState<File | null>(null);
    33:  const [check, setCheck] = useState<CheckState>({ kind: "idle" });
    34:  const fileRef = useRef<HTMLInputElement>(null);
    35:
    36:  const onFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    37:    const file = event.target.files?.[0];
    38:    if (!file) return;
    39:    setPhotoUrl(URL.createObjectURL(file));
    40:    setPhotoFile(file);
    41:    setCaptured(true);
    42:    setCheck({ kind: "idle" });
    43:  };
    44:
    45:  async function fileToBase64(file: File): Promise<{ imageBase64: string; mimeType: string }> {
    46:    const buffer = await file.arrayBuffer();
    47:    const bytes = new Uint8Array(buffer);
    48:    let binary = "";
    49:    for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
    50:    return { imageBase64: btoa(binary), mimeType: file.type || "image/jpeg" };
    51:  }
    52:
    53:  async function handleCheckPill() {
    54:    if (!photoFile || !medicationId) return;
    55:    setCheck({ kind: "checking" });
    56:    try {
    57:      const { imageBase64, mimeType } = await fileToBase64(photoFile);
    58:      // Try verify first — if it fails with 409 (no saved description), fall back to describe.
    59:      try {
    60:        const result = await api.verifyPill(medicationId, imageBase64, mimeType);
    61:        setCheck({ kind: "verified", result });
    62:      } catch (verifyError) {
    63:        // 409 = no saved description yet → this is the first time
    64:        if (verifyError instanceof Error && verifyError.message.includes("first")) {
    65:          const result = await api.describePill(medicationId, imageBase64, mimeType);
    66:          setCheck({ kind: "described", result });
    67:        } else {
    68:          throw verifyError;
    69:        }
    70:      }
    71:    } catch (error) {
    72:      setCheck({ kind: "error", message: error instanceof Error ? error.message : "Check failed." });
    73:    }
    74:  }
    75:
    76:  return (
    77:    <FullCard back={back} backLabel={t("proof.notNow")} className="scan-card">
    78:      <p className="eyebrow green">{captured ? t("proof.eyebrowFound", { name: petName }) : t("proof.eyebrowCheck")}</p>
    79:      <h2>{captured ? t("proof.titleFound") : t("proof.titleShow", { name: petName })}</h2>
    80:      <p className="supporting">{captured ? t("proof.supportingFound", { name: petName }) : t("proof.supportingShow")}</p>
    81:
    82:      <label className={`scanner proof-scanner ${captured ? "captured" : ""}`}>
    83:        {captured && photoUrl ? (
    84:          <>
    85:            <img src={photoUrl} alt="Proof photo" style={{ maxWidth: "100%", borderRadius: "12px" }} />
    86:            <strong>{t("proof.verified")}</strong>
    87:            {medicationName && <small>{medicationName}</small>}
    88:          </>
    89:        ) : (
    90:          <>
    91:            <span className="camera-orb"><Icon name="camera" size={30} /></span>
    92:            <strong>{t("proof.tapPhoto")}</strong>
    93:            <small>{t("proof.onePill")}</small>
    94:          </>
    95:        )}
    96:        <input
    97:          ref={fileRef}
    98:          type="file"
    99:          accept="image/*"
   100:          capture="environment"
   101:          onChange={onFileChange}
   102:          style={{ display: "none" }}
   103:          aria-label={t("proof.tapPhoto")}
   104:        />
   105:      </label>
   106:
   107:      {/* T2-08: Pill recognition (demo only) */}
   108:      {captured && medicationId && (
   109:        <div style={{ marginTop: "0.75rem" }}>
   110:          {check.kind === "idle" && (
   111:            <button className="secondary-button" onClick={() => void handleCheckPill()}>
   112:              Check pill with AI
   113:            </button>
   114:          )}
   115:          {check.kind === "checking" && (
   116:            <p className="supporting" style={{ fontSize: "0.9em" }}>Checking pill…</p>
   117:          )}
   118:          {check.kind === "described" && (
   119:            <div style={{ padding: "0.75rem", borderRadius: "12px", background: "var(--surface-soft, #f0fdf4)", border: "1px solid var(--green-accent, #86efac)" }}>
   120:              <small style={{ fontWeight: 600 }}>First photo saved</small>
   121:              <p style={{ fontSize: "0.85em", marginTop: "0.25rem" }}>{check.result.description}</p>
   122:              <p style={{ fontSize: "0.8em", opacity: 0.7, marginTop: "0.25rem" }}>
   123:                Next time you take this medicine, the AI will compare the photo to this description.
   124:              </p>
   125:            </div>
   126:          )}
   127:          {check.kind === "verified" && (
   128:            <div style={{ padding: "0.75rem", borderRadius: "12px", background: check.result.match ? "var(--surface-soft, #f0fdf4)" : "#fef3c7", border: `1px solid ${check.result.match ? "#86efac" : "#fcd34d"}` }}>
   129:              <small style={{ fontWeight: 600 }}>{check.result.match ? "Match — same medicine" : "No match — different medicine?"}</small>
   130:              <p style={{ fontSize: "0.85em", marginTop: "0.25rem" }}>
   131:                <strong>Saved:</strong> {check.result.savedDescription}
   132:              </p>
   133:              <p style={{ fontSize: "0.85em", marginTop: "0.25rem" }}>
   134:                <strong>This photo:</strong> {check.result.newDescription}
   135:              </p>
   136:              <p style={{ fontSize: "0.8em", opacity: 0.7, marginTop: "0.25rem" }}>
   137:                Similarity: {Math.round(check.result.similarity * 100)}%
   138:              </p>
   139:            </div>
   140:          )}
   141:          {check.kind === "error" && (
   142:            <p className="supporting" style={{ fontSize: "0.85em", color: "#dc2626" }}>{check.message}</p>
   143:          )}
   144:        </div>
   145:      )}
   146:
   147:      {/* T2-02 safety: never identify a pill from a photo */}
   148:      {captured && (
   149:        <p className="supporting" style={{ fontSize: "0.85em" }}>
   150:          The photo is saved as proof only. The app cannot identify a pill from a photo.
   151:          Always check the package and ask your pharmacist.
   152:        </p>
   153:      )}
   154:
   155:      {captured && <button className="primary-button" onClick={() => void onVerified(photoUrl)}>{t("proof.giveHeart", { name: petName })}</button>}
   156:    </FullCard>
   157:  );
   158:}
